export class HttpError extends Error {
  readonly status: number;

  constructor(status: number) {
    super('HTTP error: ' + status);
    this.name = 'HttpError';
    this.status = status;
  }
}

export async function readJsonOrNull(response: Response): Promise<unknown> {
  // 第一层：HTTP 状态检查，非 2xx 直接抛出，不进入解析
  if (!response.ok) {
    throw new HttpError(response.status);
  }

  // 第二层：成功但没有内容，明确返回 null
  if (response.status === 204) {
    return null;
  }

  // 第三层：读取并解析 JSON，解析失败会抛错
  return response.json();
}

import { HttpError, readJsonOrNull } from './api/readResponse';

async function run(): Promise<void> {
  const okResponse = new Response('{"id":1}', {
    status: 200,
    headers: { 'content-type': 'application/json' },
  });
  const emptyResponse = new Response(null, { status: 204 });
  const missingResponse = new Response('Not Found', { status: 404 });

  const data = await readJsonOrNull(okResponse);
  console.log('200 ->', data);

  const empty = await readJsonOrNull(emptyResponse);
  console.log('204 ->', empty);

  try {
    await readJsonOrNull(missingResponse);
  } catch (error) {
    if (error instanceof HttpError) {
      console.log('404 -> HttpError', error.status);
    } else {
      console.log('404 -> 其它失败', error);
    }
  }
}

run();
